// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE, LogFile} from "../src/BANK_SAFE.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    BANK_SAFE c;
    Attacker attacker;

    function setUp() public { c = new BANK_SAFE(); }

    // fuzzed params: attacker private key seed (so address varies) and deposit/withdraw amount
    function testFuzz_property(uint256 keySeed, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep domains sensible
        vm.assume(amount > 0);
        // produce an EOA address for the attacker
        address attackerEOA = vm.addr(uint256(keccak256(abi.encodePacked(keySeed))));
        // deploy an attacker contract that will reenter once when receiving ETH
        attacker = new Attacker(c);

        // Set up LogFile so Collect/Deposit won't revert on external Log calls
        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));

        // fund attacker EOA and attacker contract so it can deposit and receive
        vm.deal(attackerEOA, amount * 3 + 1 ether);
        vm.deal(address(attacker), amount * 3 + 1 ether);

        // attackerEOA will call Deposit to set its balances
        vm.prank(attackerEOA);
        c.Deposit{value: amount * 2}(); // deposit some funds

        // also allow the attacker contract to be the recipient by making attackerEOA set the attacker's address
        // but C uses msg.sender for balances; so we have attacker contract perform Deposit to set its own balance
        vm.prank(address(attacker));
        c.Deposit{value: amount}();

        // Ensure MinSum is small so Collect guard passes
        c.SetMinSum(1);

        // Now arrange for the attacker contract to re-enter when receiving the withdrawal.
        // Configure attacker to attempt to call c.Collect for amount (reentrantly) once.
        attacker.configureReentry(amount);

        // Now perform the Collect call from attacker contract (this is the initial external call that will trigger reentry)
        // The test property: after Collect returns successfully, balances(attacker) == previous - amount
        uint256 beforeBal = c.balances(address(attacker));

        // ensure attacker contract has enough balance in C to withdraw
        vm.assume(beforeBal >= amount);

        // make the call and record whether it succeeded
        bool ok;
        vm.prank(address(attacker));
        try c.Collect{value: 0}(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If call succeeded, reference contract ensures the mapping decreased by amount regardless of reentry.
        // The mutant that subtracts after external call can be manipulated by reentry to leave balances unchanged.
        if (ok) {
            uint256 afterBal = c.balances(address(attacker));
            assertTrue(afterBal == beforeBal - amount);
        } else {
            // If the call reverted, still assertTrue reads a property of c (revert case allowed to be false for the universal property),
            // but requirement is that reference passes for ALL inputs — in reference, with our setup call should succeed, so ok should be true.
            // To keep single assertTrue and read c's behavior, assert that ok is true (call succeeded) — this reads behavior via try/catch.
            assertTrue(ok);
        }
    }
}

// Attacker contract: on receive, re-enters once by calling c.Collect again to exploit delayed balance update
contract Attacker {
    BANK_SAFE public c;
    uint256 public reentryAmount;
    bool private entered;

    constructor(BANK_SAFE _c) {
        c = _c;
    }

    function configureReentry(uint256 _am) external {
        reentryAmount = _am;
        entered = false;
    }

    receive() external payable {
        // re-enter exactly once
        if (!entered) {
            entered = true;
            // attempt reentrant Collect; this will only succeed on reference if balances already decreased
            // but we call it to force the mutant-visible behavior difference
            // We ignore revert of inner call
            try c.Collect{value: 0}(reentryAmount) {
            } catch {
            }
        }
    }
}
